package com.own.order.domain; import java.util.Date; import javax.persistence.*;
@Entity @Table(name="ord_logistics_trace") public class LogisticsTrace { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="sub_order_no",nullable=false,length=64) private String subOrderNo; @Column(name="trace_status",nullable=false,length=64) private String traceStatus; @Column(nullable=false,length=500) private String detail; @Column(name="actor_id",nullable=false) private Long actorId; @Column(name="created_at",nullable=false) private Date createdAt; protected LogisticsTrace(){} public LogisticsTrace(String subOrderNo,String traceStatus,String detail,Long actorId){this.subOrderNo=subOrderNo;this.traceStatus=traceStatus;this.detail=detail;this.actorId=actorId;this.createdAt=new Date();} public String getSubOrderNo(){return subOrderNo;} public String getTraceStatus(){return traceStatus;} public String getDetail(){return detail;} public Date getCreatedAt(){return createdAt;} }
